// Only new articles arrive here: the Actor's "onlyNew" mode skips anything earlier runs returned.
const rows = $input.all().map((i) => i.json).filter((a) => a.title);
if (!rows.length) return [];
const many = new Set(rows.map((a) => a.query)).size > 1;
const lines = rows.slice(0, 15).map((a) => `• <${a.url || a.googleLink}|${a.title}> (${a.source || a.domain}${a.publishedText ? `, ${a.publishedText}` : ''})${many ? ` [${a.query}]` : ''}`);
const more = rows.length > 15 ? `\n…and ${rows.length - 15} more` : '';
return [{ json: { message: `📰 ${rows.length} new article${rows.length > 1 ? 's' : ''}${many ? '' : ` about "${rows[0].query}"`}:\n${lines.join('\n')}${more}` } }];
